import './style.css'
import { ApiError, borrowTool, fetchTools, returnTool, type ToolStatus, type ToolView } from './api.ts'

const statusLabels: Record<ToolView['status'], string> = {
  available: 'Verfügbar',
  borrowed: 'Ausgeliehen',
}

const filterOptions: { status: ToolStatus | undefined; label: string }[] = [
  { status: undefined, label: 'Alle' },
  { status: 'available', label: 'Verfügbar' },
  { status: 'borrowed', label: 'Ausgeliehen' },
]

let currentFilter: ToolStatus | undefined = undefined
let latestRequestId = 0

function escapeHtml(value: string): string {
  return value
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;')
}

function renderAction(tool: ToolView): string {
  if (tool.status === 'available') {
    return `
      <form class="loan-form" data-tool-id="${escapeHtml(tool.id)}">
        <input type="text" name="borrower" placeholder="Name" required />
        <button type="submit">Ausleihen</button>
        <p class="loan-error"></p>
      </form>`
  }
  return `
      <form class="return-form" data-tool-id="${escapeHtml(tool.id)}">
        <button type="submit">Zurückgeben</button>
        <p class="return-error"></p>
      </form>`
}

function renderTools(tools: ToolView[]): string {
  const rows = tools
    .map(
      (tool) => `
        <tr>
          <td>${escapeHtml(tool.name)}</td>
          <td>${escapeHtml(tool.id)}</td>
          <td>${escapeHtml(tool.condition)}</td>
          <td class="status status--${tool.status}">${statusLabels[tool.status]}</td>
          <td>${renderAction(tool)}</td>
        </tr>`,
    )
    .join('')

  return `
    <section id="tools">
      <h1>Werkzeugliste</h1>
      <table>
        <thead>
          <tr>
            <th>Bezeichnung</th>
            <th>Inventarnummer</th>
            <th>Zustand</th>
            <th>Status</th>
            <th>Aktion</th>
          </tr>
        </thead>
        <tbody>${rows}</tbody>
      </table>
    </section>
  `
}

function renderFilterBar(): string {
  const buttons = filterOptions
    .map(({ status, label }) => {
      const classAttr = status === currentFilter ? ' class="active"' : ''
      return `<button type="button" data-status="${status ?? ''}"${classAttr}>${label}</button>`
    })
    .join('')
  return `<div class="filter-bar">${buttons}</div>`
}

function attachFilterHandlers(app: HTMLDivElement) {
  app.querySelectorAll<HTMLButtonElement>('.filter-bar button').forEach((button) => {
    button.addEventListener('click', () => {
      const value = button.dataset.status
      currentFilter = value === undefined || value === '' ? undefined : (value as ToolStatus)
      loadAndRender(app)
    })
  })
}

function attachLoanFormHandlers(app: HTMLDivElement) {
  app.querySelectorAll<HTMLFormElement>('.loan-form').forEach((form) => {
    form.addEventListener('submit', (event) => {
      event.preventDefault()
      const toolId = form.dataset.toolId!
      const input = form.elements.namedItem('borrower') as HTMLInputElement
      const button = form.querySelector<HTMLButtonElement>('button[type="submit"]')!
      const errorEl = form.querySelector<HTMLParagraphElement>('.loan-error')!
      input.disabled = true
      button.disabled = true
      borrowTool(toolId, input.value)
        .then(() => loadAndRender(app))
        .catch((err) => {
          errorEl.textContent = err instanceof ApiError ? err.message : String(err)
          input.disabled = false
          button.disabled = false
        })
    })
  })
}

function attachReturnFormHandlers(app: HTMLDivElement) {
  app.querySelectorAll<HTMLFormElement>('.return-form').forEach((form) => {
    form.addEventListener('submit', (event) => {
      event.preventDefault()
      const toolId = form.dataset.toolId!
      const button = form.querySelector<HTMLButtonElement>('button[type="submit"]')!
      const errorEl = form.querySelector<HTMLParagraphElement>('.return-error')!
      button.disabled = true
      returnTool(toolId)
        .then(() => loadAndRender(app))
        .catch((err) => {
          errorEl.textContent = err instanceof ApiError ? err.message : String(err)
          button.disabled = false
        })
    })
  })
}

async function loadAndRender(app: HTMLDivElement) {
  const requestId = ++latestRequestId
  try {
    const tools = await fetchTools(currentFilter)
    if (requestId !== latestRequestId) return
    app.innerHTML = renderFilterBar() + renderTools(tools)
  } catch (err) {
    if (requestId !== latestRequestId) return
    console.error(err)
    app.innerHTML = renderFilterBar() + '<p>Werkzeugliste konnte nicht geladen werden.</p>'
  }
  attachFilterHandlers(app)
  attachLoanFormHandlers(app)
  attachReturnFormHandlers(app)
}

async function init() {
  const app = document.querySelector<HTMLDivElement>('#app')!
  await loadAndRender(app)
}

init()

export type ToolStatus = "available" | "borrowed";

export interface ToolView {
  id: string;
  name: string;
  condition: string;
  status: ToolStatus;
  loan: { borrower: string; borrowedAt: string } | null;
}

export async function fetchTools(status?: ToolStatus): Promise<ToolView[]> {
  const url = status === undefined ? "/api/tools" : `/api/tools?status=${status}`;
  const res = await fetch(url);
  if (!res.ok) {
    throw new Error(`GET /api/tools failed with status ${res.status}`);
  }
  const body = (await res.json()) as { tools: ToolView[] };
  return body.tools;
}

export class ApiError extends Error {
  code: string;
  constructor(code: string, message: string) {
    super(message);
    this.code = code;
  }
}

export async function borrowTool(id: string, borrower: string): Promise<ToolView> {
  const res = await fetch(`/api/tools/${encodeURIComponent(id)}/loan`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ borrower }),
  });
  let body: { tool: ToolView } | { error: { code: string; message: string } };
  try {
    body = (await res.json()) as { tool: ToolView } | { error: { code: string; message: string } };
  } catch {
    throw new ApiError("UNKNOWN_ERROR", "Die Antwort des Servers konnte nicht gelesen werden.");
  }
  if (!res.ok) {
    const { error } = body as { error: { code: string; message: string } };
    throw new ApiError(error.code, error.message);
  }
  return (body as { tool: ToolView }).tool;
}

export async function returnTool(id: string): Promise<ToolView> {
  const res = await fetch(`/api/tools/${encodeURIComponent(id)}/return`, {
    method: "POST",
  });
  let body: { tool: ToolView } | { error: { code: string; message: string } };
  try {
    body = (await res.json()) as { tool: ToolView } | { error: { code: string; message: string } };
  } catch {
    throw new ApiError("UNKNOWN_ERROR", "Die Antwort des Servers konnte nicht gelesen werden.");
  }
  if (!res.ok) {
    const { error } = body as { error: { code: string; message: string } };
    throw new ApiError(error.code, error.message);
  }
  return (body as { tool: ToolView }).tool;
}

import type { State, ToolView } from "./types.ts";
import { toToolView } from "./tool-view.ts";

export type BorrowResult =
  | { ok: true; tool: ToolView }
  | {
      ok: false;
      error: { code: "VALIDATION_ERROR" | "TOOL_NOT_FOUND" | "ALREADY_BORROWED"; message: string };
    };

export function borrowTool(
  state: State,
  toolId: string,
  borrower: string | undefined,
  now: Date,
): { state: State; result: BorrowResult } {
  const trimmedBorrower = typeof borrower === "string" ? borrower.trim() : "";
  if (trimmedBorrower.length === 0) {
    return {
      state,
      result: {
        ok: false,
        error: { code: "VALIDATION_ERROR", message: "Bitte einen Namen angeben." },
      },
    };
  }

  const tool = state.tools.find((candidate) => candidate.id === toolId);
  if (tool === undefined) {
    return {
      state,
      result: {
        ok: false,
        error: { code: "TOOL_NOT_FOUND", message: "Werkzeug nicht gefunden." },
      },
    };
  }

  const existingLoan = state.loans.find((candidate) => candidate.toolId === toolId);
  if (existingLoan !== undefined) {
    return {
      state,
      result: {
        ok: false,
        error: { code: "ALREADY_BORROWED", message: "Dieses Werkzeug ist bereits ausgeliehen." },
      },
    };
  }

  const newLoan = { toolId, borrower: trimmedBorrower, borrowedAt: now.toISOString() };
  const nextState: State = { tools: state.tools, loans: [...state.loans, newLoan] };
  return { state: nextState, result: { ok: true, tool: toToolView(tool, nextState.loans) } };
}

export type ReturnResult =
  | { ok: true; tool: ToolView }
  | { ok: false; error: { code: "TOOL_NOT_FOUND" | "NOT_BORROWED"; message: string } };

export function returnTool(state: State, toolId: string): { state: State; result: ReturnResult } {
  const tool = state.tools.find((candidate) => candidate.id === toolId);
  if (tool === undefined) {
    return {
      state,
      result: {
        ok: false,
        error: { code: "TOOL_NOT_FOUND", message: "Werkzeug nicht gefunden." },
      },
    };
  }

  const existingLoan = state.loans.find((candidate) => candidate.toolId === toolId);
  if (existingLoan === undefined) {
    return {
      state,
      result: {
        ok: false,
        error: { code: "NOT_BORROWED", message: "Dieses Werkzeug ist nicht ausgeliehen." },
      },
    };
  }

  const nextState: State = { tools: state.tools, loans: state.loans.filter((loan) => loan.toolId !== toolId) };
  return { state: nextState, result: { ok: true, tool: toToolView(tool, nextState.loans) } };
}

import express, { type Express } from "express";
import path from "node:path";
import type { Repository } from "../data/repository.ts";
import { filterToolsByStatus, toToolView } from "../domain/tool-view.ts";
import { borrowTool, returnTool, type BorrowResult, type ReturnResult } from "../domain/loan.ts";

export function createApp(clientDistPath: string, repository: Repository): Express {
  const app = express();
  app.use(express.json());

  const apiRouter = express.Router();
  apiRouter.get("/tools", (req, res) => {
    const state = repository.getState();
    const status = typeof req.query.status === "string" ? req.query.status : undefined;
    const tools = filterToolsByStatus(state.tools.map((tool) => toToolView(tool, state.loans)), status);
    res.json({ tools });
  });
  apiRouter.post("/tools/:id/loan", async (req, res) => {
    const borrower = typeof req.body?.borrower === "string" ? req.body.borrower : undefined;
    let result: BorrowResult;
    try {
      result = await repository.mutate((state) => borrowTool(state, req.params.id, borrower, new Date()));
    } catch {
      res.status(500).json({ error: { code: "INTERNAL_ERROR", message: "Ein interner Fehler ist aufgetreten." } });
      return;
    }
    if (result.ok) {
      res.status(201).json({ tool: result.tool });
      return;
    }
    const statusByCode = { VALIDATION_ERROR: 400, TOOL_NOT_FOUND: 404, ALREADY_BORROWED: 409 } as const;
    res.status(statusByCode[result.error.code]).json({ error: result.error });
  });
  apiRouter.post("/tools/:id/return", async (req, res) => {
    let result: ReturnResult;
    try {
      result = await repository.mutate((state) => returnTool(state, req.params.id));
    } catch {
      res.status(500).json({ error: { code: "INTERNAL_ERROR", message: "Ein interner Fehler ist aufgetreten." } });
      return;
    }
    if (result.ok) {
      res.status(200).json({ tool: result.tool });
      return;
    }
    const statusByCode = { TOOL_NOT_FOUND: 404, NOT_BORROWED: 409 } as const;
    res.status(statusByCode[result.error.code]).json({ error: result.error });
  });
  app.use("/api", apiRouter);

  app.use(express.static(clientDistPath));
  app.get("/*splat", (_req, res) => {
    res.sendFile(path.join(clientDistPath, "index.html"));
  });

  return app;
}

import { mkdir, readFile, rename, rm, writeFile } from "node:fs/promises";
import path from "node:path";
import type { State } from "../domain/types.ts";

export interface Repository {
  mutate<R>(fn: (state: State) => { state: State; result: R }): Promise<R>;
  getState(): State;
}

function emptyState(): State {
  return { tools: [], loans: [] };
}

async function readExistingState(dataFilePath: string): Promise<State | null> {
  let raw: string;
  try {
    raw = await readFile(dataFilePath, "utf8");
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code === "ENOENT") {
      return null;
    }
    throw err;
  }
  if (raw.trim().length === 0) {
    return null;
  }
  return JSON.parse(raw) as State;
}

async function writeStateAtomically(dataFilePath: string, state: State): Promise<void> {
  const dir = path.dirname(dataFilePath);
  await mkdir(dir, { recursive: true });
  const tempFilePath = path.join(dir, `.${path.basename(dataFilePath)}.${process.pid}.${Date.now()}.tmp`);
  await writeFile(tempFilePath, JSON.stringify(state, null, 2), "utf8");
  try {
    await rename(tempFilePath, dataFilePath);
  } catch (err) {
    await rm(tempFilePath, { force: true });
    throw err;
  }
}

export async function createRepository(dataFilePath: string): Promise<Repository> {
  const existingState = await readExistingState(dataFilePath);
  let state: State = existingState ?? emptyState();

  if (existingState === null) {
    await writeStateAtomically(dataFilePath, state);
  }

  // Serializes mutate() calls: each call is chained onto the previous one,
  // so read -> decide -> write per call runs atomically with respect to others (AD-3).
  let queue: Promise<unknown> = Promise.resolve();

  function mutate<R>(fn: (state: State) => { state: State; result: R }): Promise<R> {
    const task = queue.then(async () => {
      const { state: nextState, result } = fn(state);
      await writeStateAtomically(dataFilePath, nextState);
      state = nextState;
      return result;
    });
    queue = task.catch(() => {});
    return task;
  }

  function getState(): State {
    return state;
  }

  return { mutate, getState };
}

export interface Tool {
  id: string;
  name: string;
  condition: string;
}

export interface Loan {
  toolId: string;
  borrower: string;
  borrowedAt: string;
}

export interface State {
  tools: Tool[];
  loans: Loan[];
}

export type ToolStatus = "available" | "borrowed";

export interface ToolView {
  id: string;
  name: string;
  condition: string;
  status: ToolStatus;
  loan: { borrower: string; borrowedAt: string } | null;
}
import type { Loan, Tool, ToolView } from "./types.ts";

export function toToolView(tool: Tool, loans: Loan[]): ToolView {
  const loan = loans.find((candidate) => candidate.toolId === tool.id);
  if (loan === undefined) {
    return { id: tool.id, name: tool.name, condition: tool.condition, status: "available", loan: null };
  }
  return {
    id: tool.id,
    name: tool.name,
    condition: tool.condition,
    status: "borrowed",
    loan: { borrower: loan.borrower, borrowedAt: loan.borrowedAt },
  };
}

export function filterToolsByStatus(tools: ToolView[], status: string | undefined): ToolView[] {
  if (status === "available" || status === "borrowed") {
    return tools.filter((tool) => tool.status === status);
  }
  return tools;
}

