.filter-bar {
  display: flex;
  gap: 8px;
  margin-bottom: 16px;
}

.filter-bar button {
  font: inherit;
  color: var(--text);
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 6px 12px;
  cursor: pointer;
}

.filter-bar button.active {
  color: var(--text-h);
  border-color: var(--text-h);
  font-weight: 600;
}

.loan-form {
  display: flex;
  gap: 6px;
  align-items: center;
}

.loan-form input {
  width: 100px;
  font: inherit;
}

.loan-error {
  margin: 0;
  color: var(--borrowed);
  font-size: 14px;
}

